var n=`0148-shah-plov`;var t=`world-0148`;var i=`AZ`;var s=`western-asia`;var r=4;var l=83;var o={en:`Shah Plov`,ua:`Шах-плов`};var d={en:`A classic dish from Azerbaijan, featuring basmati rice, lamb shoulder, yellow onion, chestnut. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: рис басматі, лопатка ягняти, жовта цибуля, каштан їстівний. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var u=[{en:`Rinse rice and parboil in salted water until just slightly underdone, about 10–12 minutes. Drain carefully.`,ua:`Промийте рис і відваріть у підсоленій воді до стану трохи недовареного, 10–12 хвилин. Обережно відцідіть.`,t:[`boiling`],m:12,i:[[`basmati-rice`,420,`g`],[`water`,1150,`ml`],[`table-salt`,5,`g`]]},{en:`Brown lamb with onion and butter, then add chestnuts and dried fruit; cook until aromatic and nearly tender.`,ua:`Підрум’яньте баранину з цибулею та маслом, додайте каштани й сухофрукти та приготуйте майже до м’якості.`,t:[`chopping`,`sauteing`],m:14,i:[[`lamb-shoulder`,450,`g`],[`yellow-onion`,170,`g`],[`unsalted-butter`,65,`g`],[`chestnut`,170,`g`],[`raisin`,80,`g`],[`dried-apricot`,100,`g`]]},{en:`Line a buttered deep ovenproof pot with overlapping lavash strips. Layer rice and filling inside, sprinkle with saffron-infused water and fold the lavash over to seal.`,ua:`Вистеліть змащену глибоку жаростійку каструлю смугами лаваша внапусток. Викладіть шарами рис і начинку, збризніть шафрановою водою та закрийте лавашем.`,t:[`layered-assembly`],m:14,i:[[`lavash`,300,`g`],[`saffron-threads`,.3,`g`],[`water`,65,`ml`]]},{en:`Bake the lavash-covered plov until its shell is crisp and golden, then carefully turn out onto a platter and cut into wedges.`,ua:`Запікайте до хрусткої золотистої оболонки, обережно переверніть плов на тацю й наріжте скибками.`,t:[`baking`],m:40,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,35,`g`]]}];var h={slug:n,id:t,country:`AZ`,region:s,servings:4,minutes:83,title:o,text:d,steps:u};export{i as country,h as default,t as id,l as minutes,s as region,r as servings,n as slug,u as steps,d as text,o as title};